// Vendor lifecycle, LIF-11: sign-in ignores the case of the email address.
import { PASSWORD, expect, expectStatus, test } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test("sign-in ignores the case of the email address", { tag: "@LIF-11" }, async ({ request }) => {
    // Arrange
    const email = "Member@Northwind.TEST";

    // Act
    const login = await request.post("/api/auth/login", {
      data: { email, password: PASSWORD },
    });

    // Assert
    const { access_token: token } = await expectStatus<{ access_token: string }>(login, 200);
    const me = await request.get("/api/me", {
      headers: { Authorization: `Bearer ${token}` },
    });
    const profile = await expectStatus<{ email: string }>(me, 200);
    expect(profile.email).toBe("member@northwind.test");
  });
});
